local Vec2 = ____Dora.Vec2
local View = ____Dora.View
local ____palette = require("core.palette")
local Palette = ____palette.Palette
local function clamp(____, v, lo, hi)
    return math.min(
        hi,
        math.max(lo, v)
    )
end
local function lerp(____, a, b, u)
    return a + (b - a) * u
end
local function smooth(____, a, b, t)
    local u = clamp(nil, (t - a) / (b - a), 0, 1)
    return u * u * (3 - 2 * u)
end
local function hash(____, n)
    local s = math.sin(n * 127.1 + 311.7) * 43758.5453
    return s - math.floor(s)
end
local function col(____, c, alphaMul)
    return Color(
        nil,
        c.r,
        c.g,
        c.b,
        math.floor(c.a * (alphaMul == nil and 1 or clamp(nil, alphaMul, 0, 1)) + 0.5)
    )
end
local function circlePts(____, cx, cy, r, seg)
    local pts = {}
    do
        local i = 0
        while i < seg do
            local a = i / seg * math.pi * 2
            pts[#pts + 1] = Vec2(
                nil,
                cx + math.cos(a) * r,
                cy + math.sin(a) * r
            )
            i = i + 1
        end
    end
    return pts
end
local function ring(____, d, cx, cy, r, seg, w, c, a0, a1)
    local from = a0 == nil and 0 or a0
    local to = a1 == nil and math.pi * 2 or a1
    local px = cx + math.cos(from) * r
    local py = cy + math.sin(from) * r
    do
        local i = 1
        while i <= seg do
            local ang = from + (to - from) * i / seg
            local nx = cx + math.cos(ang) * r
            local ny = cy + math.sin(ang) * r
            d:drawSegment(
                Vec2(nil, px, py),
                Vec2(nil, nx, ny),
                w,
                c
            )
            px = nx
            py = ny
            i = i + 1
        end
    end
end
local function rectPts(____, x, y, w, h)
    return {
        Vec2(nil, x, y),
        Vec2(nil, x + w, y),
        Vec2(nil, x + w, y + h),
        Vec2(nil, x, y + h)
    }
end
local function sectorPts(____, cx, cy, r, a0, a1, seg)
    local pts = {Vec2(nil, cx, cy)}
    do
        local i = 0
        while i <= seg do
            local a = a0 + (a1 - a0) * i / seg
            pts[#pts + 1] = Vec2(
                nil,
                cx + math.cos(a) * r,
                cy + math.sin(a) * r
            )
            i = i + 1
        end
    end
    return pts
end
