    local function ridgeY(____, wx, base, amp, seed)
        return base + amp * (0.55 * math.sin(wx * 0.0042 + seed) + 0.3 * math.sin(wx * 0.0113 + seed * 2.1) + 0.15 * math.sin(wx * 0.027 + seed * 0.7))
    end
    local function drawRidge(____, d, base, amp, seed, drift, c)
        local pts = {}
        do
            local x = -W / 2 - 60
            while x <= W / 2 + 60 do
                pts[#pts + 1] = Vec2(
                    nil,
                    x,
                    ridgeY(
                        nil,
                        x + drift,
                        base,
                        amp,
                        seed
                    )
                )
                x = x + 48
            end
        end
        pts[#pts + 1] = Vec2(nil, W / 2 + 60, -H / 2 - 80)
        pts[#pts + 1] = Vec2(nil, -W / 2 - 60, -H / 2 - 80)
