    local function pathPos(____, p)
        local u = clamp(nil, p, 0, 1) * (#climbPath - 1)
        local i = math.min(
            math.floor(u),
            #climbPath - 2
        )
        local f = u - i
        return {
            x = lerp(nil, climbPath[i + 1].x, climbPath[i + 1 + 1].x, f),
            y = lerp(nil, climbPath[i + 1].y, climbPath[i + 1 + 1].y, f)
        }
    end
    local function drawPolyline(____, d, pts, u, c, w)
        local total = #pts - 1
        local f = clamp(nil, u, 0, 1) * total
        local full = math.floor(f)
        do
            local i = 0
            while i < full do
                d:drawSegment(pts[i + 1], pts[i + 1 + 1], w, c)
                i = i + 1
            end
        end
        if full < total and full >= 0 then
            local fr = f - full
            d:drawSegment(
                pts[full + 1],
                Vec2(
                    nil,
                    lerp(nil, pts[full + 1].x, pts[full + 1 + 1].x, fr),
                    lerp(nil, pts[full + 1].y, pts[full + 1 + 1].y, fr)
                ),
                w,
                c
            )
        end
    end
