    local function drawBeam(____, d, tx0, ty0, a)
        if a <= 0.01 then
            return
        end
        local dx = tx0 - MX
        local dy = ty0 - MY
        local len = math.sqrt(dx * dx + dy * dy)
        local ux = dx / len
        local uy = dy / len
        local px = -uy
        local py = ux
        local function quad(____, w0, w1, c)
            d:drawPolygon(
                {
                    Vec2(nil, MX + px * w0, MY + py * w0),
                    Vec2(nil, tx0 + px * w1, ty0 + py * w1),
                    Vec2(nil, tx0 - px * w1, ty0 - py * w1),
                    Vec2(nil, MX - px * w0, MY - py * w0)
                },
                c
            )
        end
        quad(
            nil,
            16,
            40,
            col(nil, Palette.goldSoft, a * 0.85)
        )
        quad(
            nil,
            7,
            20,
            col(nil, Palette.moonWhite, a)
        )
