                local ang = rot + i / 8 * math.pi * 2
                local ca = math.cos(ang)
                local sa = math.sin(ang)
                d:drawSegment(
                    Vec2(nil, cx + ca * 22, cy + sa * 22),
                    Vec2(nil, cx + ca * (WHEEL_R - 4), cy + sa * (WHEEL_R - 4)),
                    3,
                    col(nil, Palette.gold, a)
                )
                local sx = cx + ca * (WHEEL_R + 20)
                local sy = cy + sa * (WHEEL_R + 20)
