    local function torchPos(____, i, tt)
        local sx = -W / 2 + 50 + i * 26
        local sy = BANK - 10 + i * 3
        local ex = TX - 150 + i * 12
        local ey = TBY + 10
        local p = smooth(nil, 11 + i * 0.28, 13.6 + i * 0.12, tt)
        local on = smooth(nil, 11 + i * 0.28, 11.35 + i * 0.28, tt)
        local out = 1 - smooth(nil, 15, 15.8, tt)
        return {
            x = lerp(nil, sx, ex, p),
            y = lerp(nil, sy, ey, p) - p * 24,
            a = on * out
        }
    end
