                    Vec2(nil, MX + rw / 2 + i * 6, ry),
                    3,
                    col(nil, Palette.moonWhite, a * (0.75 - i * 0.12))
                )
                i = i + 1
            end
        end
        local reeds = {
            -W / 2 + 90,
            -W / 2 + 120,
            -W / 2 + 150,
            W / 2 - 120,
            W / 2 - 90
        }
        do
            local i = 0
            while i < #reeds do
                local rx = reeds[i + 1]
                d:drawSegment(
                    Vec2(nil, rx, BANK + 2),
                    Vec2(nil, rx + (i % 2 == 0 and 8 or -8), BANK + 30 + i % 3 * 8),
                    2.5,
                    col(nil, Palette.inkSoft, a)
                )
                i = i + 1
            end
        end
        drawFigure(
            nil,
            d,
            -170,
            BANK + 2,
            1.15,
            a,
            false,
            "back"
        )
        drawFigure(
            nil,
            d,
            150,
            BANK + 2,
            1.1,
            a,
            true,
            "stand"
        )
    end
    local function drawBubble(____, d, a)
        if a <= 0.01 then
            return
        end
        local bw = 170
        local bh = 58
        local x0 = BUBX - bw / 2
        local y0 = BUBY - bh / 2
        local r = 10
        local fill = col(nil, Palette.paper, a)
        local outline = col(nil, Palette.inkDark, a)
        d:drawPolygon(
            rectPts(
                nil,
                x0,
                y0,
                bw,
                bh
            ),
            fill
        )
        local border = {
            Vec2(nil, x0, y0 + r),
            Vec2(nil, x0 + r, y0),
            Vec2(nil, x0 + bw - r, y0),
            Vec2(nil, x0 + bw, y0 + r),
            Vec2(nil, x0 + bw, y0 + bh - r),
            Vec2(nil, x0 + bw - r, y0 + bh),
            Vec2(nil, x0 + r, y0 + bh),
            Vec2(nil, x0, y0 + bh - r),
            Vec2(nil, x0, y0 + r)
        }
        do
            local i = 0
            while i < #border - 1 do
                d:drawSegment(border[i + 1], border[i + 1 + 1], 2.5, outline)
                i = i + 1
            end
        end
        d:drawPolygon(
            {
                Vec2(nil, BUBX - 26, y0 + 1),
                Vec2(nil, BUBX - 2, y0 + 1),
                Vec2(nil, BUBX - 18, y0 - 20)
            },
            fill
        )
        d:drawSegment(
            Vec2(nil, BUBX - 26, y0 + 1),
            Vec2(nil, BUBX - 18, y0 - 20),
            2.5,
            outline
        )
        d:drawSegment(
            Vec2(nil, BUBX - 18, y0 - 20),
            Vec2(nil, BUBX - 2, y0 + 1),
            2.5,
            outline
        )
    end
    local SCENE_B = 21.45
    local function wipeRadius(____, tt)
        local maxR = math.sqrt(W / 2 * (W / 2) + H / 2 * (H / 2)) + 30
        if tt < SCENE_B then
            return maxR * smooth(nil, 20.5, SCENE_B, tt)
        end
        return maxR * (1 - smooth(nil, 21.55, 22.4, tt))
    end
    local t = 0
    local finished = false
    local function finalize()
        if finished then
            return
        end
        finished = true
        root.visible = false
        onFinish(nil)
    end
    local function subAlpha(____, i)
        local s = SUBS[i + 1]
        return smooth(nil, s.from, s.from + 0.4, t) * (1 - smooth(nil, s.to - 0.4, s.to, t))
    end
    local function render()
        local fadeIn = smooth(nil, 0, 3.5, t)
        local sceneB = t >= SCENE_B
        do
            bgDraw:clear()
            bgDraw:drawPolygon(
                rectPts(
                    nil,
                    -W / 2,
                    -H / 2,
                    W,
                    H
                ),
                col(nil, Palette.paper)
            )
            if not sceneB then
                bgDraw:drawDot(
                    Vec2(nil, MX, MY),
                    MR + 52,
                    col(nil, Palette.moonHalo, fadeIn)
                )
                bgDraw:drawPolygon(
                    circlePts(
                        nil,
                        MX,
                        MY,
                        MR,
                        32
                    ),
                    col(nil, Palette.moonWhite, fadeIn)
                )
                bgDraw:drawDot(
                    Vec2(nil, MX - 30, MY + 34),
                    14,
                    col(nil, Palette.paleInkFar, fadeIn * 0.5)
                )
                bgDraw:drawDot(
                    Vec2(nil, MX + 24, MY - 20),
                    10,
                    col(nil, Palette.paleInkFar, fadeIn * 0.4)
                )
                local cu = smooth(nil, 8, 10.6, t)
                if cu > 0.01 then
                    local cc = col(nil, Palette.moonWhite, 0.95 * cu * fadeIn)
                    drawPolyline(
                        nil,
                        bgDraw,
                        crackMain,
                        cu,
                        cc,
                        2
                    )
                    drawPolyline(
                        nil,
                        bgDraw,
                        crackBranch1,
                        smooth(nil, 8.9, 10.6, t),
                        cc,
                        1.6
                    )
                    drawPolyline(
                        nil,
                        bgDraw,
                        crackBranch2,
                        smooth(nil, 9.6, 10.6, t),
                        cc,
                        1.6
                    )
                end
                drawRidge(
                    nil,
                    bgDraw,
                    H / 2 - 210,
                    55,
                    1.3,
                    24 + 6 * t,
                    col(nil, Palette.paleInkFar, fadeIn)
                )
                drawRidge(
                    nil,
                    bgDraw,
                    H / 2 - 140,
                    75,
                    4.2,
                    40 + 11 * t,
                    col(nil, Palette.paleInkMid, fadeIn)
                )
                drawTown(
                    nil,
                    bgDraw,
                    col(nil, Palette.inkSoft, fadeIn * 0.95)
                )
            else
                drawRiverside(
                    nil,
                    bgDraw,
                    smooth(nil, SCENE_B, 22.4, t),
                    t
                )
            end
        end
        do
            sceneDraw:clear()
            if not sceneB then
                drawTower(
                    nil,
                    sceneDraw,
                    smooth(nil, 3.5, 4.6, t)
                )
                local cp = smooth(nil, 3.7, 8, t)
                if t < 14.5 then
                    local fpos = pathPos(
                        nil,
                        math.min(cp / 0.92, 1)
                    )
                    local mpos = pathPos(
                        nil,
                        math.max(cp / 0.92 - 0.08, 0)
                    )
                    local walkPose = cp >= 1 and "stand" or "walk"
                    drawFigure(
                        nil,
                        sceneDraw,
                        fpos.x,
                        fpos.y,
                        0.8,
                        fadeIn,
                        true,
                        walkPose
                    )
                    drawFigure(
                        nil,
                        sceneDraw,
                        mpos.x,
                        mpos.y,
                        0.8,
                        fadeIn,
                        false,
                        walkPose
                    )
                else
                    local u5 = t - 14.5
                    local topY = TTY + 12
                    local pushU = smooth(nil, 0.55, 0.95, u5)
                    local hitU = smooth(nil, 1.1, 1.5, u5)
                    local wx = lerp(nil, TX - 16, TX - 86, pushU)
                    local mx2 = lerp(nil, TX + 6, TX - 30, hitU)
                    local mAlpha = 1 - smooth(nil, 1.7, 2.4, u5)
                    local bxA = lerp(
                        nil,
                        TX + 180,
                        TX + 46,
                        smooth(nil, 0, 0.9, u5)
                    )
                    drawBandit(
                        nil,
                        sceneDraw,
                        bxA,
                        topY,
                        1,
                        smooth(nil, 0, 0.4, u5) * (1 - smooth(nil, 2.2, 2.5, u5))
                    )
                    drawBeam(
                        nil,
                        sceneDraw,
                        mx2,
                        topY + 16,
                        smooth(nil, 1.05, 1.25, u5) * (1 - smooth(nil, 1.6, 1.95, u5))
                    )
                    local fPose = u5 > 1.7 and "kneel" or (pushU > 0 and pushU < 1 and "walk" or "stand")
                    drawFigure(
                        nil,
                        sceneDraw,
                        wx,
                        topY,
                        1,
                        1,
                        true,
                        fPose
                    )
                    local mPose = hitU >= 1 and "lie" or (u5 > 0.5 and u5 < 1 and "push" or "stand")
                    drawFigure(
                        nil,
                        sceneDraw,
                        mx2,
                        topY,
                        1,
                        mAlpha,
                        false,
                        mPose
                    )
                end
                if t >= 10.8 and t <= 15.9 then
                    do
                        local i = 0
                        while i < 8 do
                            local tp = torchPos(nil, i, t)
                            if tp.a > 0.02 then
                                sceneDraw:drawDot(
                                    Vec2(nil, tp.x, tp.y),
                                    9,
                                    col(nil, Palette.vermilion, 0.18 * tp.a)
                                )
                                sceneDraw:drawDot(
                                    Vec2(nil, tp.x, tp.y),
                                    4.5,
                                    col(nil, Palette.vermilion, tp.a)
                                )
                            end
                            i = i + 1
                        end
                    end
                end
                if t >= 17 and t < SCENE_B then
                    local hover = t > 18.2 and 4 * math.sin((t - 18.2) * 2) or 0
                    local wy = lerp(
                        nil,
                        H / 2 + 180,
                        WHEEL_CY,
                        smooth(nil, 17, 18.2, t)
                    ) + hover
                    drawWheel(
                        nil,
                        sceneDraw,
                        0,
                        wy,
                        1.2 * (t - 17) * (t - 17),
                        smooth(nil, 17, 17.7, t)
                    )
                end
            end
        end
        do
            fxDraw:clear()
            local bubA = smooth(nil, 22.7, 23.1, t)
            if bubA > 0.02 then
                drawBubble(nil, fxDraw, bubA)
            end
            local fl = smooth(nil, 8, 8.5, t) * (1 - smooth(nil, 10.4, 11, t))
            if fl > 0.01 then
                fxDraw:drawPolygon(
                    rectPts(
                        nil,
                        -W / 2,
                        -H / 2,
                        W,
                        H
                    ),
                    col(
                        nil,
                        Palette.moonHalo,
                        fl * (0.45 + 0.45 * math.sin(t * 9))
                    )
                )
            end
            local wr = wipeRadius(nil, t)
            if wr > 1 then
                fxDraw:drawPolygon(
                    circlePts(
                        nil,
                        0,
                        0,
                        wr,
                        48
                    ),
                    col(nil, Palette.inkDark)
                )
            end
            local endA = smooth(nil, 23, DURATION, t)
            if endA > 0.01 then
                fxDraw:drawPolygon(
                    rectPts(
                        nil,
                        -W / 2,
                        -H / 2,
                        W,
                        H
                    ),
                    col(nil, Palette.paper, endA)
                )
            end
        end
        local si = -1
        local sa = 0
        do
            local i = 0
            while i < #SUBS do
                local a2 = subAlpha(nil, i)
                if a2 > sa then
                    sa = a2
                    si = i
                end
                i = i + 1
            end
        end
        do
            uiDraw:clear()
            if sa > 0.01 then
                uiDraw:drawPolygon(
                    rectPts(
                        nil,
                        -W / 2,
                        SUBY - 24,
                        W,
                        48
                    ),
                    col(nil, Palette.paperDim, 0.55 * sa)
                )
            end
        end
        if subLb ~= nil then
            subLb.visible = si >= 0 and sa > 0.02
            if si >= 0 then
                subLb.text = SUBS[si + 1].text
            end
            subLb.opacity = si >= 0 and sa or 0
        end
        if hintLb ~= nil then
            hintLb.opacity = smooth(nil, 1, 2.2, t) * 0.9
        end
        if bubLb ~= nil then
            local bubA = smooth(nil, 22.7, 23.1, t)
            bubLb.visible = bubA > 0.02
            bubLb.opacity = bubA
        end
        if t >= 11 and t <= 14.5 then
            local k = 1 - (t - 11) / 3.5
            local amp = 8 * k * k
            local fi = math.floor(t * 28)
            sceneRoot.position = Vec2(
                nil,
                (hash(nil, fi) * 2 - 1) * amp,
                (hash(nil, fi + 57) * 2 - 1) * amp
            )
        else
            sceneRoot.position = Vec2(nil, 0, 0)
        end
    end
    WHEEL_CY = 40
    local function doSkip()
        if finished then
            return
        end
        t = DURATION
        render(nil)
        finalize(nil)
    end
    return {
        update = function(self, dt)
            if finished then
                return
            end
            if t > 0.15 and (Keyboard:isKeyDown(KeyName.Space) or Keyboard:isKeyDown(KeyName.J) or Keyboard:isKeyDown(KeyName.E) or Keyboard:isKeyDown(KeyName.Return)) then
                doSkip(nil)
                return
            end
            t = t + dt
            if t > DURATION then
                t = DURATION
            end
            render(nil)
            if t >= DURATION then
                finalize(nil)
            end
        end,
        skip = function(self)
            doSkip(nil)
        end,
        done = function(self)
            return finished
        end
    }
end
return ____exports
